const CONFIRM_TEXT = "You asked to subscribe to a Knox DSA mailing list. Click below to confirm, and you’ll start getting what you signed up for.\n\nConfirm your subscription: {{confirm_url}}\n\nIf you didn’t request this, ignore this email and nothing will happen.\n\nQuestions? Email bobby@knoxvilledsa.org.\n\nIn solidarity,\n\nBobby, Knox DSA\n";

// letterhead.markup.link, in JavaScript: the URL if it is plainly http or
// https, otherwise "". Same refusal to raise, because the caller decides what
// to do about a link it cannot show.
export function houseLink(value) {
  const raw = String(value == null ? "" : value).trim();
  const head = raw.slice(0, 8).toLowerCase();
  return head.startsWith("http://") || head.startsWith("https://") ? raw : "";
}

// Takes the full confirm URL. Returns { subject, html, text }.
